```yaml
name: Auto-close PRs referencing unready issues

on:
  pull_request:
    types: [opened, edited]

permissions:
  pull-requests: write
  issues: read
  contents: read

jobs:
  close-unready-pr:
    runs-on: ubuntu-latest
    steps:
      - name: Close PR if it references an unready issue
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const body = pr.body || '';
            const issueRegex = /(?:https?:\/\/[^\/]+\/[^\/]+\/[^\/]+\/issues\/([0-9]+)|#([0-9]+))/g;
            const matches = [...body.matchAll(issueRegex)];
            if (matches.length !== 1) {
              console.log('Skipping: zero or multiple issue references');
              return;
            }
            const issueNumber = matches[0][1] || matches[0][2];
            const issueNumberInt = parseInt(issueNumber, 10);
            const issue = await github.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: issueNumberInt
            });
            const cutoff = new Date('2026-03-10T00:00:00Z');
            if (new Date(issue.data.created_at) < cutoff) {
              console.log('Skipping: issue created before cutoff');
              return;
            }
            const hasReady = issue.data.labels.some(l => l.name === 'ready');
            if (hasReady) {
              console.log('Skipping: issue has ready label');
              return;
            }
            const authorAssoc = pr.author_association;
            if (['MEMBER', 'OWNER', 'NONE'].includes(authorAssoc)) {
              console.log('Skipping: PR author is maintainer or bot');
              return;
            }
            const comment = `This PR references issue #${issueNumber} which hasn't been triaged yet (missing the \`ready\` label). Please add the \`ready\` label before reopening.`;
            await github.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: comment
            });
            await github.pulls.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pr.number,
              state: 'closed'
            });
            console.log('PR closed due to unready issue');
